// Spring Boot - PCI DSS Security Headers Configuration
// SecurityConfig.java

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.header.writers.ReferrerPolicyHeaderWriter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            // Enforce HTTPS
            .requiresChannel(channel -> channel
                .anyRequest().requiresSecure()
            )

            // Security Headers
            .headers(headers -> headers
                // HSTS - Required for PCI DSS
                .httpStrictTransportSecurity(hsts -> hsts
                    .maxAgeInSeconds(31536000)  // 1 year
                    .includeSubDomains(true)
                    .preload(true)
                )

                // Content Security Policy - Recommended for PCI DSS
                .contentSecurityPolicy(csp -> csp
                    .policyDirectives(
                        "default-src 'self'; " +
                        "script-src 'self'; " +
                        "style-src 'self' 'unsafe-inline'; " +
                        "img-src 'self' data: https:; " +
                        "font-src 'self'; " +
                        "connect-src 'self'; " +
                        "frame-ancestors 'none'; " +
                        "base-uri 'self'; " +
                        "form-action 'self'; " +
                        "upgrade-insecure-requests"
                    )
                )

                // X-Frame-Options - Required for PCI DSS
                .frameOptions(frame -> frame
                    .deny()
                )

                // X-Content-Type-Options - Required for PCI DSS
                .contentTypeOptions()

                // Referrer Policy - Recommended for PCI DSS
                .referrerPolicy(referrer -> referrer
                    .policy(ReferrerPolicyHeaderWriter.ReferrerPolicy
                        .STRICT_ORIGIN_WHEN_CROSS_ORIGIN)
                )
            )

            // Session Management - PCI DSS compliant
            .sessionManagement(session -> session
                .maximumSessions(1)  // Prevent concurrent sessions
                .maxSessionsPreventsLogin(true)
            )

            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/payment/**").authenticated()
                .anyRequest().permitAll()
            );

        return http.build();
    }
}

// application.properties - Secure Cookie Configuration
// Required for PCI DSS
server.servlet.session.cookie.secure=true
server.servlet.session.cookie.http-only=true
server.servlet.session.cookie.same-site=strict
server.servlet.session.timeout=30m

// Force HTTPS
server.ssl.enabled=true
server.ssl.key-store=classpath:keystore.p12
server.ssl.key-store-password=${SSL_KEYSTORE_PASSWORD}
server.ssl.key-store-type=PKCS12
server.ssl.key-alias=tomcat

// TLS Configuration - PCI DSS compliant
server.ssl.protocol=TLS
server.ssl.enabled-protocols=TLSv1.2,TLSv1.3
server.ssl.ciphers=TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256

