// JUnit test for PCI DSS headers
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
public class PciComplianceTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void shouldHaveHstsHeader() throws Exception {
        mockMvc.perform(get("/"))
            .andExpect(status().isOk())
            .andExpect(header().exists("Strict-Transport-Security"))
            .andExpect(header().string("Strict-Transport-Security",
                containsString("max-age=31536000")))
            .andExpect(header().string("Strict-Transport-Security",
                containsString("includeSubDomains")));
    }

    @Test
    public void shouldHaveXFrameOptions() throws Exception {
        mockMvc.perform(get("/"))
            .andExpect(header().string("X-Frame-Options", "DENY"));
    }

    @Test
    public void shouldHaveContentSecurityPolicy() throws Exception {
        mockMvc.perform(get("/"))
            .andExpect(header().exists("Content-Security-Policy"))
            .andExpect(header().string("Content-Security-Policy",
                containsString("default-src 'self'")));
    }

    @Test
    public void shouldHaveXContentTypeOptions() throws Exception {
        mockMvc.perform(get("/"))
            .andExpect(header().string("X-Content-Type-Options", "nosniff"));
    }

    @Test
    public void cookiesShouldBeSecure() throws Exception {
        mockMvc.perform(get("/payment"))
            .andExpect(cookie().secure("JSESSIONID", true))
            .andExpect(cookie().httpOnly("JSESSIONID", true));
    }
}

