// Express.js - PCI DSS Security Headers

const express = require('express');
const helmet = require('helmet');
const https = require('https');
const fs = require('fs');

const app = express();

// 1. Use Helmet for security headers
app.use(helmet({
  // HSTS - Required for PCI DSS
  strictTransportSecurity: {
    maxAge: 31536000,  // 1 year in seconds
    includeSubDomains: true,
    preload: true
  },

  // Content Security Policy - Recommended
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
      frameAncestors: ["'none'"],
      baseUri: ["'self'"],
      formAction: ["'self'"],
      upgradeInsecureRequests: []
    }
  },

  // X-Frame-Options - Required
  frameguard: {
    action: 'deny'
  },

  // X-Content-Type-Options - Required
  noSniff: true,

  // Referrer Policy - Recommended
  referrerPolicy: {
    policy: 'strict-origin-when-cross-origin'
  }
}));

// 2. Enforce HTTPS
app.use((req, res, next) => {
  if (req.secure || req.headers['x-forwarded-proto'] === 'https') {
    next();
  } else {
    // Redirect HTTP to HTTPS
    res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
});

// 3. Secure Session Configuration
const session = require('express-session');
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: true,      // HTTPS only
    httpOnly: true,    // No JavaScript access
    sameSite: 'strict', // CSRF protection
    maxAge: 1800000    // 30 minutes
  }
}));

// 4. HTTPS Server Configuration
const httpsOptions = {
  key: fs.readFileSync('./ssl/private-key.pem'),
  cert: fs.readFileSync('./ssl/certificate.pem'),

  // TLS 1.2+ only for PCI DSS
  minVersion: 'TLSv1.2',
  maxVersion: 'TLSv1.3',

  // Strong cipher suites
  ciphers: [
    'ECDHE-RSA-AES256-GCM-SHA384',
    'ECDHE-RSA-AES128-GCM-SHA256',
    'ECDHE-RSA-AES256-SHA384',
    'ECDHE-RSA-AES128-SHA256'
  ].join(':'),

  honorCipherOrder: true
};

// 5. Payment Routes (require authentication)
app.post('/api/payment', requireAuth, (req, res) => {
  // Process payment
  // Never log or store full card numbers
  res.json({ status: 'success' });
});

// Start HTTPS server
https.createServer(httpsOptions, app).listen(443, () => {
  console.log('PCI DSS compliant HTTPS server running on port 443');
});

// Optional: HTTP server that redirects to HTTPS
const http = require('http');
http.createServer((req, res) => {
  res.writeHead(301, { Location: `https://${req.headers.host}${req.url}` });
  res.end();
}).listen(80);

