# Nginx - PCI DSS Security Headers Configuration
# /etc/nginx/sites-available/payment-app

server {
    listen 80;
    server_name payment.example.com;

    # Redirect all HTTP to HTTPS (required for PCI DSS)
    return 301 https://$server_name$request_uri;
}

server {
    listen 443 ssl http2;
    server_name payment.example.com;

    # SSL/TLS Configuration - PCI DSS compliant
    ssl_certificate /etc/ssl/certs/payment.crt;
    ssl_certificate_key /etc/ssl/private/payment.key;

    # TLS 1.2 and 1.3 only (PCI DSS requirement)
    ssl_protocols TLSv1.2 TLSv1.3;

    # Strong cipher suites (PCI DSS approved)
    ssl_ciphers 'ECDHE-RSA-AES256-GCM-SHA384:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-RSA-AES256-SHA384:ECDHE-RSA-AES128-SHA256';
    ssl_prefer_server_ciphers on;

    # SSL session cache
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;

    # Security Headers - PCI DSS Required

    # HSTS - REQUIRED for PCI DSS
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;

    # X-Frame-Options - REQUIRED
    add_header X-Frame-Options "DENY" always;

    # X-Content-Type-Options - REQUIRED
    add_header X-Content-Type-Options "nosniff" always;

    # Content Security Policy - RECOMMENDED
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; font-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'; upgrade-insecure-requests" always;

    # Referrer Policy - RECOMMENDED
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # Disable server version disclosure
    server_tokens off;

    # Secure cookie configuration
    # Note: Application must also set Secure, HttpOnly, SameSite
    proxy_cookie_path / "/; Secure; HttpOnly; SameSite=Strict";

    location / {
        proxy_pass http://backend_app;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Timeouts
        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
    }

    # Payment processing endpoints (extra security)
    location /payment/ {
        # Rate limiting
        limit_req zone=payment burst=5 nodelay;

        proxy_pass http://backend_app;
        proxy_set_header Host $host;

        # Logging (PCI DSS requirement)
        access_log /var/log/nginx/payment-access.log combined;
        error_log /var/log/nginx/payment-error.log warn;
    }

    # Health check endpoint (no security headers needed)
    location /health {
        access_log off;
        return 200 "healthy\n";
    }
}

# Rate limiting zone for payment endpoints
http {
    limit_req_zone $binary_remote_addr zone=payment:10m rate=10r/s;
}

