// Selenium test for PCI DSS compliance
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.testng.annotations.Test;
import static org.testng.Assert.*;

public class PciComplianceTest {

    @Test
    public void testHttpsEnforcement() {
        WebDriver driver = new ChromeDriver();

        // Try HTTP
        driver.get("http://payment.example.com");

        // Should redirect to HTTPS
        String currentUrl = driver.getCurrentUrl();
        assertTrue(currentUrl.startsWith("https://"),
            "Should redirect to HTTPS");

        driver.quit();
    }

    @Test
    public void testSecurityHeaders() throws Exception {
        // Use HttpClient to check headers
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(new URI("https://payment.example.com"))
            .build();

        HttpResponse<String> response = client.send(
            request,
            HttpResponse.BodyHandlers.ofString()
        );

        // Verify HSTS
        String hsts = response.headers()
            .firstValue("Strict-Transport-Security")
            .orElse("");
        assertTrue(hsts.contains("max-age=31536000"));

        // Verify X-Frame-Options
        String xfo = response.headers()
            .firstValue("X-Frame-Options")
            .orElse("");
        assertEquals("DENY", xfo);
    }
}
